"use client";
import { cn } from "@/lib/utils";
import { useRef, useState } from "react";
import { ArrowUp, Check, LoaderCircle, Undo2 } from "lucide-react";
import { panel } from "@/lib/takt-surface";
export function PromptBox({
  className,
  onSend,
  suggestions = ["Find an idea", "Refine the task"],
}: {
  className?: string;
  suggestions?: string[];
  onSend?: (text: string) => void | Promise<void>;
}) {
  const [text, setText] = useState("");
  const [last, setLast] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(false);
  const field = useRef<HTMLTextAreaElement>(null);
  const pending = useRef(false);
  async function send() {
    const message = text.trim();
    if (!message || pending.current) return;
    pending.current = true;
    setBusy(true);
    setError(false);
    try {
      await onSend?.(message);
      setLast(message);
      setText("");
    } catch {
      setError(true);
    } finally {
      pending.current = false;
      setBusy(false);
    }
  }
  return (
    <form
      className={cn(panel + " grid w-72 max-w-full gap-2", className)}
      onSubmit={(e) => {
        e.preventDefault();
        void send();
      }}
    >
      {last && (
        <div className="flex items-center gap-1.5 rounded-lg bg-muted px-2 py-1.5 text-xs motion-safe:animate-in motion-safe:slide-in-from-bottom-1">
          <Check size={13} />
          <output className="min-w-0 flex-1 truncate">{last}</output>
          <button
            type="button"
            aria-label="Edit previous prompt"
            disabled={busy}
            onClick={() => {
              setText(last);
              setLast("");
              field.current?.focus();
            }}
          >
            <Undo2 size={14} />
          </button>
        </div>
      )}
      {!text && !last && suggestions.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {suggestions.map((v) => (
            <button
              type="button"
              className="rounded-md border bg-muted px-2.5 py-1.5 text-[11px] hover:bg-background"
              key={v}
              onClick={() => {
                setText(v);
                field.current?.focus();
              }}
            >
              {v}
            </button>
          ))}
        </div>
      )}
      <textarea
        ref={field}
        rows={2}
        aria-label="Prompt"
        readOnly={busy}
        placeholder="What would you like to ask?"
        value={text}
        onChange={(e) => {
          setText(e.target.value);
          setError(false);
        }}
        onKeyDown={(e) => {
          if (e.nativeEvent.isComposing || e.keyCode === 229) return;
          if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
            e.preventDefault();
            void send();
          }
        }}
        className="min-w-0 resize-none rounded-md bg-transparent px-1 text-sm leading-relaxed outline-offset-2"
      />
      <div className="flex items-center justify-between border-t pt-2">
        <small role="status" className="text-[10px] text-muted-foreground">
          {error ? "Could not send" : "Shift + Enter · new line"}
        </small>
        <button
          type="submit"
          aria-label="Send"
          disabled={busy || !text.trim()}
          className="grid size-8 place-items-center rounded-full bg-primary text-primary-foreground motion-safe:transition-transform motion-safe:active:scale-90 disabled:opacity-35"
        >
          {busy ? (
            <LoaderCircle className="motion-safe:animate-spin" size={15} />
          ) : (
            <ArrowUp size={16} />
          )}
        </button>
      </div>
    </form>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
